{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Ketanserin, a high-transfer analogue with an arylpiperidine/piperazine-like core, has absolute oral bioavailability of 55.5 ± 8.7% in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Meperidine, a high-transfer analogue with moderate first-pass metabolism, has measured oral F ranging from 0.40 to 0.60 (average 0.50) in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Thalidomide, a high-transfer small molecule, has oral bioavailability estimated at 80–100% in fasting healthy volunteers, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Eltoprazine, a high-transfer arylpiperazine, has an absolute bioavailability of about 95%, supporting high oral bioavailability for structurally related piperazine-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "CAB, a high-transfer fused heteroaromatic piperazine, shows near-complete oral bioavailability in humans, supporting high F for the query's piperazine-bearing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Bexagliflozin, a high-transfer oral drug, has an absolute bioavailability of about 78% in humans, providing additional support for F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues have measured or estimated oral bioavailability at or above ~50% in humans, far above the 20% threshold. The query's arylpiperazine-butoxy-dihydroquinolinone structure is consistent with these well-absorbed, modest-first-pass compounds, so F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct bioavailability measurement for the query molecule itself is included; prediction relies on high-transfer analogues.",
    "Some supporting records are qualitative (e.g., 'excellent', 'high') rather than numeric F values.",
    "One qualitative record lists meperidine as low oral bioavailability, but direct F measurements for meperidine are 40–61%, so it is not considered threshold-relevant affirmative evidence for low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

